const fs = require('fs');

let cfg;
try {
  cfg = JSON.parse(fs.readFileSync('/data/notifications/config.json', 'utf8'));
} catch (e) {
  throw new Error('Cannot read /data/notifications/config.json — did you fill in your Telegram token and chat ID?');
}

if (!cfg.notify_on_error) return [];
if (cfg.telegram_bot_token === 'YOUR_BOT_TOKEN_HERE') {
  throw new Error('Please set telegram_bot_token in notifications/config.json');
}

const err = $input.first().json;
const wfName   = err.workflow?.name || 'Unknown workflow';
const errMsg   = err.execution?.error?.message || 'No error message';
const execId   = err.execution?.id || '';
const execTime = new Date().toLocaleString('en-IN', { timeZone: cfg.timezone || 'Asia/Kolkata' });

const message = [
  `🚨 <b>Workflow Failed</b>`,
  ``,
  `📋 <b>Workflow:</b> ${wfName}`,
  `❌ <b>Error:</b> ${errMsg}`,
  `🕐 <b>Time:</b> ${execTime}`,
  execId ? `🔗 <b>Execution ID:</b> ${execId}` : '',
  ``,
  `<i>— ${cfg.project_name || 'Automate Hub'}</i>`
].filter(Boolean).join('\n');

return [{
  json: {
    token:   cfg.telegram_bot_token,
    chat_id: cfg.telegram_chat_id,
    message
  }
}];
